  "Applies on Generate, except turning a GC content, GC skew or Depth row on or off, removing one, and Use custom stack, which apply at once; turning on a row added since the last Generate, a row that was off when the Session was loaded, or a Depth row after a Depth file change apply on Generate, and so does Use custom stack after a Session load (except turned off on a Linear Result drawn with it) or while the Region Annotation sets differ from those of the Result, with every track it would hide or show": "생성 시 적용됩니다. 단, GC 함량 행, GC skew 행 또는 깊이 행을 켜거나 끄는 것, 그러한 행을 제거하는 것, ‘사용자 지정 스택 사용’은 즉시 적용됩니다. 마지막 생성 이후 추가한 행, 세션을 불러왔을 때 꺼져 있던 행, 리드 깊이 파일을 변경한 후의 깊이 행을 켜는 것은 생성 시 적용되며, ‘사용자 지정 스택 사용’도 세션을 불러온 후(이 옵션으로 그린 선형 다이어그램의 결과에서 끄는 경우 제외)나 영역 주석 세트가 결과의 세트와 다른 동안에는 이 옵션으로 숨기거나 표시할 모든 트랙과 함께 생성 시 적용됩니다",
  "Applies the live circular track arrangement used while Custom Track Slots is off. Custom Track Slots inherit this preset when enabled.": "‘사용자 지정 트랙 슬롯’이 꺼져 있는 동안 사용되는 원형 다이어그램의 트랙 배치를 적용합니다. ‘사용자 지정 트랙 슬롯’을 활성화하면 이 프리셋을 상속합니다.",
  "Applies to SVG and Interactive SVG exports, not to Generate.": "SVG 및 대화형 SVG 내보내기에 적용되며, 생성에는 적용되지 않습니다.",
