  "Auto Reflow failed. Current diagram is kept.": "자동 재배치에 실패했습니다. 현재 다이어그램은 유지됩니다.",
  "Auto chooses threaded LOSAT only when browser support and workload allow it.": "‘자동’은 브라우저 지원과 작업량이 허용할 때만 다중 스레드 LOSAT을 선택합니다.",
  "Auto embeds labels that fit and routes the rest externally. Embedded Only drops labels that need external placement. External Only keeps labels outside feature bodies.": "‘자동’은 feature 안에 들어가는 레이블은 내부에 배치하고 나머지는 외부에 배치합니다. ‘내부 배치만’은 외부 배치가 필요한 레이블을 생략합니다. ‘외부 배치만’은 레이블을 feature 본체 바깥에 둡니다.",
  "Auto follows the track layout (Above or Features on axis: labels above; Below: labels below). Above Feature draws labels above features (and below negative-strand features when Separate Strands is on).": "‘자동’은 트랙 레이아웃을 따릅니다(‘위쪽’ 또는 ‘축상 feature’: 레이블을 위쪽에 배치, ‘아래쪽’: 레이블을 아래쪽에 배치). ‘feature 위쪽’은 레이블을 feature 위쪽에 그립니다(‘가닥별 표시’가 켜져 있으면 − 가닥 feature의 레이블은 아래쪽에 그립니다).",
  "Auto hides these fields throughout the diagram": "‘자동’은 다이어그램 전체에서 이 필드를 숨깁니다",
  "Auto makes the CDSs that share a locus identifier one unit and every other CDS a unit of its own. CDS makes each CDS a unit. Locus makes each locus a unit and requires a locus identifier, such as /locus_tag, on every CDS.": "‘자동’은 같은 유전자좌 식별자를 가진 CDS를 하나의 유닛으로 묶고, 나머지 CDS는 각각 하나의 유닛으로 만듭니다. ‘CDS’는 각 CDS를 하나의 유닛으로 만듭니다. ‘유전자좌’는 각 유전자좌를 하나의 유닛으로 만들며, 모든 CDS에 유전자좌 식별자(예: /locus_tag)가 있어야 합니다.",
  "Auto shows these fields throughout the diagram": "‘자동’은 다이어그램 전체에서 이 필드를 표시합니다",
  "Auto will hide these fields throughout the diagram on the next successful Generate": "‘자동’은 다음 생성이 성공하면 다이어그램 전체에서 이 필드를 숨깁니다",
  "Auto will show these fields throughout the diagram on the next successful Generate": "‘자동’은 다음 생성이 성공하면 다이어그램 전체에서 이 필드를 표시합니다",
