  "Band (annotation lane)": "밴드(주석 레인)",
  "Bar (Simple)": "막대(단순)",
  "Base colors for features, comparison tracks, and collinear blocks. The selected palette supplies unchanged colors; colors you edit override it; when you change the palette, a dialog asks whether to keep them.": "feature, 비교 트랙, 공선성 블록의 기본 색입니다. 변경하지 않은 색은 선택한 팔레트의 색을 사용하고, 편집한 색은 팔레트보다 우선합니다. 팔레트를 변경하면 편집한 색을 유지할지 대화 상자에서 묻습니다.",
  "Base text shown in the diagram legend. Leave blank to use the auto label shown here; two-color tracks add (+) and (-).": "다이어그램 범례에 표시되는 기본 텍스트입니다. 비워 두면 여기에 표시된 자동 레이블을 사용합니다. 두 가지 색으로 그리는 트랙에는 (+)와 (-)가 추가됩니다.",
