  "Browser-oriented SVG with embedded controls. Rich Feature Popup controls how much feature detail is embedded.": "조작용 컨트롤이 포함된 브라우저용 SVG입니다. 포함할 feature 세부 정보의 양은 ‘상세 feature 팝업’에서 정합니다.",
