  "Choose Show in Record Labels to keep a field visible.": "필드를 계속 표시하려면 ‘레코드 레이블’에서 ‘표시’를 선택하십시오.",
  "Choose a BLAST TSV for each pair, or skip these comparisons.": "각 쌍의 BLAST TSV를 선택하거나 이 비교를 건너뛰십시오.",
  "Choose a BLAST TSV for this pair, or set the pair to No comparison or Run LOSAT.": "이 쌍의 BLAST TSV를 선택하거나, 쌍을 ‘비교 없음’ 또는 ‘LOSAT 실행’으로 설정하십시오.",
  "Choose a LOSATN task that the selected LOSAT runtime supports.": "선택한 LOSAT 런타임에서 지원하는 LOSATN 태스크를 선택하십시오.",
