  "Choose a readable TrueType or OpenType font file (.ttf, .otf, .ttc, .otc) that names its font family.": "글꼴 패밀리 이름이 들어 있고 읽을 수 있는 TrueType 또는 OpenType 글꼴 파일(.ttf, .otf, .ttc, .otc)을 선택하십시오.",
