  "Choose the placement Overlay anchor (Circular) or On axis (Linear) when an anchor or an Extend to slot is selected.": "앵커 또는 ‘연장 대상’ 슬롯을 선택한 경우 배치로 ‘오버레이 앵커’(원형) 또는 ‘축상’(선형)을 선택하십시오.",
