  "Color features whose qualifier value matches a regular expression, case-insensitive (for example NADH). Choose a suggested qualifier or type any qualifier name. When rules use the same qualifier, the first matching row wins; Move rule up and down changes that order. Rules on different qualifiers are tried in the order the qualifiers appear on the feature.": "한정자 값이 정규식(예: NADH)과 일치하는 feature에 색을 지정합니다. 대소문자는 구분하지 않습니다. 제안된 한정자를 선택하거나 원하는 한정자 이름을 입력하십시오. 여러 규칙이 같은 한정자를 사용하면 처음 일치하는 행이 우선하며, ‘규칙을 위로 이동’과 ‘규칙을 아래로 이동’으로 그 순서를 바꿀 수 있습니다. 서로 다른 한정자의 규칙은 feature에 한정자가 나타나는 순서대로 일치 여부를 확인합니다.",
