  "Control label visibility, filtering, text settings, and circular label geometry.": "레이블 표시 여부, 필터링, 텍스트 설정과 원형 다이어그램의 레이블 치수를 조정합니다.",
  "Control track placement and layout-related options.": "트랙 배치와 레이아웃 관련 옵션을 조정합니다.",
  "Control which feature labels are displayed using Blacklist or Whitelist. Whitelist patterns use case-insensitive Python regex search, matching the -t color table semantics.": "차단 목록 또는 허용 목록으로 표시할 feature 레이블을 제어합니다. 허용 목록 패턴은 대소문자를 구분하지 않는 Python 정규식 검색을 사용하며, -t 색 테이블과 같은 규칙으로 일치 여부를 판정합니다.",
