  "Could not import annotations: {reason}": "주석을 가져올 수 없습니다: {reason}",
  "Could not preserve decoration placement. Reset the affected position or use Reset Layout on the previous Result, or restore matching settings, then Generate again.": "장식 요소 배치를 유지할 수 없습니다. 영향을 받은 위치를 초기화하거나, 이전 결과에서 ‘레이아웃 초기화’를 사용하거나, 일치하는 설정을 복원한 다음 다시 생성하십시오.",
