  "Custom Track Slots": "사용자 지정 트랙 슬롯",
  "Custom Track Slots are active. Use an enabled Ticks slot to control coordinate-scale visibility.": "‘사용자 지정 트랙 슬롯’이 활성 상태입니다. 눈금 및 축척의 표시 여부는 활성화된 ‘눈금’ 슬롯으로 제어하십시오.",
  "Custom Track Slots must be a list of rows.": "‘사용자 지정 트랙 슬롯’은 행 목록이어야 합니다.",
  "Custom Track Slots need at least one enabled row.": "‘사용자 지정 트랙 슬롯’에는 활성화된 행이 하나 이상 필요합니다.",
  "Custom Track Slots no longer read this field. Use slot-level radius, width, inner_gap_px, outer_gap_px, side, and z fields.": "‘사용자 지정 트랙 슬롯’은 더 이상 이 필드를 읽지 않습니다. 슬롯 수준의 radius, width, inner_gap_px, outer_gap_px, side, z 필드를 사용하십시오.",
  "Custom position": "사용자 지정 위치",
  "Custom stack Depth rows control rendering. Disable the custom stack to change this simple control.": "사용자 지정 스택의 깊이 행이 렌더링을 제어합니다. 이 단순 컨트롤을 변경하려면 사용자 지정 스택을 비활성화하십시오.",
  "Custom stack geometry is active. Use each Depth row width, or Reset to copy this value into the stack.": "사용자 지정 스택 치수가 활성 상태입니다. 각 깊이 행의 너비를 사용하거나, ‘초기화’로 이 값을 스택에 복사하십시오.",
  "Custom stack geometry is active. Use the Dinucleotide content row radius, or Reset to copy this value into the stack.": "사용자 지정 스택 치수가 활성 상태입니다. ‘다이뉴클레오타이드 함량’ 행의 반지름을 사용하거나, ‘초기화’로 이 값을 스택에 복사하십시오.",
  "Custom stack geometry is active. Use the Dinucleotide content row width, or Reset to copy this value into the stack.": "사용자 지정 스택 치수가 활성 상태입니다. ‘다이뉴클레오타이드 함량’ 행의 너비를 사용하거나, ‘초기화’로 이 값을 스택에 복사하십시오.",
  "Custom stack geometry is active. Use the Dinucleotide skew row radius, or Reset to copy this value into the stack.": "사용자 지정 스택 치수가 활성 상태입니다. ‘다이뉴클레오타이드 skew’ 행의 반지름을 사용하거나, ‘초기화’로 이 값을 스택에 복사하십시오.",
  "Custom stack geometry is active. Use the Dinucleotide skew row width, or Reset to copy this value into the stack.": "사용자 지정 스택 치수가 활성 상태입니다. ‘다이뉴클레오타이드 skew’ 행의 너비를 사용하거나, ‘초기화’로 이 값을 스택에 복사하십시오.",
  "Custom stack geometry is active. Use the Features row width, or Reset to copy this value into the stack.": "사용자 지정 스택 치수가 활성 상태입니다. ‘feature’ 행의 너비를 사용하거나, ‘초기화’로 이 값을 스택에 복사하십시오.",
  "Custom stack is saved but inactive; generation uses the simple track controls.": "사용자 지정 스택은 저장되어 있지만 비활성 상태입니다. 생성에는 단순 트랙 컨트롤이 사용됩니다.",
