  "Draw one circular pairwise comparison ring per uploaded BLAST outfmt 6/7 file or browser LOSATN/TLOSATX comparison sequence file (FASTA, GenBank, or DDBJ). Reverse BLAST coordinates are shown as reverse hits, not origin-spanning hits.": "업로드한 BLAST outfmt 6/7 파일 또는 브라우저 LOSATN/TLOSATX 비교 서열 파일(FASTA, GenBank 또는 DDBJ)마다 원형 쌍별 비교 링을 하나씩 그립니다. 역방향 BLAST 좌표는 원점을 가로지르는 히트가 아니라 역방향 히트로 표시됩니다.",
