  "Edit the explicit linear track stack. Opening or closing this panel does not enable or alter the stack. Arrows reorder within the current side; Row actions move rows across the boundary.": "선형 다이어그램의 사용자 지정 트랙 스택을 편집합니다. 이 패널을 열거나 닫아도 스택이 활성화되거나 변경되지 않습니다. 화살표는 같은 쪽 안에서 행의 순서를 바꾸고, ‘행 작업’은 행을 경계 너머로 옮깁니다.",
