  "Font": "글꼴",
  "Font size": "글꼴 크기",
  "Font size for GC content percent tick labels. Leave blank for auto.": "GC 함량 백분율 눈금 레이블의 글꼴 크기입니다. 비워 두면 자동으로 설정됩니다.",
  "Font size for circular tick labels. Leave blank to use the default size.": "원형 다이어그램의 눈금 레이블 글꼴 크기입니다. 비워 두면 기본 크기를 사용합니다.",
  "Font size for feature labels.": "feature 레이블의 글꼴 크기입니다.",
  "Font size for record-label text (species/strain in circular; organism/replicon/accession/length stack in linear).": "레코드 레이블 텍스트의 글꼴 크기입니다(원형에서는 종명/균주, 선형에서는 여러 줄로 쌓인 생물명/레플리콘/등록 번호/길이).",
  "Font size for ruler tick labels, including rulers drawn on record axes.": "눈금자의 눈금 레이블 글꼴 크기입니다. 레코드 축에 그린 눈금자도 포함됩니다.",
  "Font size for the circular shared plot title. Only used when the title position is Top or Bottom.": "공유 원형 다이어그램 제목의 글꼴 크기입니다. 제목 위치가 ‘위쪽’ 또는 ‘아래쪽’일 때만 사용됩니다.",
  "Font size for the legend text.": "범례 텍스트의 글꼴 크기입니다.",
  "Font size for the linear plot title.": "선형 다이어그램 제목의 글꼴 크기입니다.",
  "Font size for the simple bar scale label.": "단순 막대 축척 레이블의 글꼴 크기입니다.",
  "Font size for this track's depth tick labels. Leave blank for auto.": "이 트랙의 깊이 눈금 레이블 글꼴 크기입니다. 비워 두면 자동으로 설정됩니다.",
  "Font {family} could not be prepared for the PDF. Its text is drawn in {substitute}.": "{family} 글꼴을 PDF용으로 준비하지 못했습니다. 해당 텍스트는 {substitute} 글꼴로 그려집니다.",
  "Font {family} is not embedded in the PDF: its license (OS/2 fsType) does not allow embedding. Its text is drawn in {substitute}.": "{family} 글꼴은 라이선스(OS/2 fsType)상 포함이 허용되지 않아 PDF에 포함하지 않았습니다. 해당 텍스트는 {substitute} 글꼴로 그려집니다.",
  "Font {family} is not embedded: its license (OS/2 fsType) does not allow embedding. The SVG shows it only where {family} is installed.": "{family} 글꼴은 라이선스(OS/2 fsType)상 포함이 허용되지 않아 SVG에 포함하지 않았습니다. SVG에서는 {family} 글꼴이 설치된 환경에서만 해당 글꼴로 표시됩니다.",
  "Fonts loaded in this page could not be prepared again for drawing. Load them again in Font, or choose another font.": "이 페이지에서 불러온 글꼴을 그리기용으로 다시 준비하지 못했습니다. ‘글꼴’에서 다시 불러오거나 다른 글꼴을 선택하십시오.",
  "For Extend to, select an eligible enabled slot other than the anchor, or None.": "‘연장 대상’에는 앵커가 아닌 조건에 맞는 활성화된 슬롯 또는 ‘없음’을 선택하십시오.",
