  "Gap between axis and nearest feature edge for Above/Below track layouts. Auto derives from feature height.": "트랙 레이아웃이 위쪽/아래쪽일 때 축과 가장 가까운 feature 가장자리 사이의 간격입니다. ‘자동’은 feature 높이에서 값을 구합니다.",
