  "Halo": "후광",
  "Halo draws a white outline around the letters of each label with a leader, so leaders behind them are cut away. Box draws a white box behind the letters. None draws neither.": "‘후광’은 지시선이 있는 각 레이블의 글자 주위에 흰색 윤곽을 그려 뒤에 있는 지시선을 가립니다. ‘상자’는 글자 뒤에 흰색 상자를 그립니다. ‘없음’은 둘 다 그리지 않습니다.",
  "Hatch": "빗금",
  "Head Length Ratio": "화살표 머리 길이 비율",
  "Head length and shaft width apply to Arrow features and remain available even when no feature currently uses that rendering.": "화살표 머리 길이와 몸통 너비는 ‘화살표’ feature에 적용되며, 현재 이 렌더링을 사용하는 feature가 없어도 설정할 수 있습니다.",
  "Head length divided by the full rendered feature thickness. Leave blank for Auto. Auto starts from the mode-specific default and lengthens the head as the shaft narrows.": "화살표 머리 길이를 렌더링된 feature 전체 두께로 나눈 값입니다. 비워 두면 ‘자동’으로 설정됩니다. ‘자동’은 모드별 기본값에서 시작하여 몸통이 가늘어질수록 머리를 길게 합니다.",
  "Height": "높이",
