  "Height of the linear GC content and GC skew tracks. Applies to whichever of those tracks are enabled when the diagram is generated.": "선형 다이어그램의 GC 함량 및 GC skew 트랙 높이입니다. 다이어그램을 생성할 때 활성화된 트랙에 적용됩니다.",
  "Height of this linear depth coverage track in px. Leave blank for auto.": "선형 다이어그램에서 이 깊이 트랙의 높이(px)입니다. 비워 두면 자동으로 설정됩니다.",
