  "Highlights render automatically behind the feature track. Line, Bracket, and Band render in a separate annotation lane. Custom Track Slots can override this automatic placement.": "강조 표시는 feature 트랙 뒤에 자동으로 그려집니다. 선, 괄호, 밴드는 별도의 주석 레인에 그려집니다. ‘사용자 지정 트랙 슬롯’에서 이 자동 배치를 재정의할 수 있습니다.",
  "Horizontal": "수평",
  "Horizontal keeps external labels level; Radial aligns them with the circle radius.": "‘수평’은 외부 레이블을 수평으로 유지하고, ‘방사형’은 원의 반지름 방향으로 맞춥니다.",
