  "Identity >= {value}%": "동일성 >= {value}%",
  "If you save a .gbdraw-session.json.gz and load it back in the web app, the uploaded inputs, results, and LOSAT cache are restored from the compressed JSON; these TSV files do not need to be saved separately for session restore.": ".gbdraw-session.json.gz를 저장한 뒤 웹 앱에서 다시 불러오면 업로드한 입력, 결과, LOSAT 캐시가 압축된 JSON에서 복원되므로, 세션 복원을 위해 이 TSV 파일을 따로 저장할 필요는 없습니다.",
  "If you use gbdraw in your research, please cite the preprint:": "연구에 gbdraw를 사용한다면 다음 프리프린트를 인용하십시오:",
  "Ignored annotation table columns: {columns}. These columns are not saved in Sessions or TSV re-export.": "무시된 주석 표 열: {columns}. 이 열은 세션에 저장되지 않으며 TSV로 다시 내보낼 때도 포함되지 않습니다.",
