  "Legend: entries {items} had a color the app does not accept and were dropped.": "범례: {items} 항목의 색을 앱에서 허용하지 않으므로 제외했습니다.",
  "Legend: entries {items} repeat an earlier entry of their list and were dropped.": "범례: {items} 항목이 목록의 앞 항목과 중복되어 제외했습니다.",
  "Legend: entry {items} had a color the app does not accept and was dropped.": "범례: {items} 항목의 색을 앱에서 허용하지 않으므로 제외했습니다.",
  "Legend: entry {items} repeats an earlier entry of its list and was dropped.": "범례: {items} 항목이 목록의 앞 항목과 중복되어 제외했습니다.",
  "Legend: the color edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "범례: ‘{label}’에 저장된 색 편집({path})을 ‘{used}’ 행으로 옮기려 했지만, 해당 행에 직접 저장된 편집이 있어 그 편집을 사용하고 이 편집은 제외했습니다.",
  "Legend: the color edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "범례: ‘{label}’에 저장된 색 편집({path})과 후속 편집이 모두 ‘{used}’ 행을 대상으로 하므로, 후속 편집을 사용하고 이 편집은 제외했습니다.",
  "Legend: the entry stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an entry of its own; that entry is used and this one was dropped.": "범례: ‘{label}’에 저장된 항목({path})을 ‘{used}’ 행으로 옮기려 했지만, 해당 행에 직접 저장된 항목이 있어 그 항목을 사용하고 이 항목은 제외했습니다.",
  "Legend: the entry stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "범례: ‘{label}’에 저장된 항목({path})과 후속 편집이 모두 ‘{used}’ 행을 대상으로 하므로, 후속 편집을 사용하고 이 항목은 제외했습니다.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; it is not used.": "범례: ‘{stored}’ 위치({path})는 해당 모드에서 사용할 수 있는 위치가 아니므로 사용하지 않습니다.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; {used} is used.": "범례: ‘{stored}’ 위치({path})는 해당 모드에서 사용할 수 있는 위치가 아니므로 {used} 위치를 사용합니다.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "범례: ‘{label}’에 저장된 윤곽선 편집({path})을 ‘{used}’ 행으로 옮기려 했지만, 해당 행에 직접 저장된 편집이 있어 그 편집을 사용하고 이 편집은 제외했습니다.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "범례: ‘{label}’에 저장된 윤곽선 편집({path})과 후속 편집이 모두 ‘{used}’ 행을 대상으로 하므로, 후속 편집을 사용하고 이 편집은 제외했습니다.",
