  "Linear track stack": "선형 다이어그램의 트랙 스택",
  "Linear vertical spacing after the track, in pixels (px optional; nonnegative). Leave blank for the automatic spacing.": "선형 다이어그램에서 트랙 뒤에 두는 세로 간격(픽셀, px 생략 가능, 0 이상)입니다. 비워 두면 자동 간격을 사용합니다.",
  "Link Linear scale and ruler label font sizes": "선형 다이어그램의 축척과 눈금자 레이블 글꼴 크기 연동",
  "Link Scale and Ruler Label Font Sizes": "축척과 눈금자 레이블 글꼴 크기 연동",
  "List all 12 standard BLAST outfmt 6 fields in the \"# Fields:\" line, or remove the line so that the first 12 columns are read in the standard order.": "‘# Fields:’ 줄에 표준 BLAST outfmt 6 필드 12개를 모두 나열하거나, 처음 12개 열이 표준 순서로 읽히도록 이 줄을 제거하십시오.",
  "Live edit": "실시간 편집",
  "Live edit applying: geometry is being updated. Direct edits already applied are kept.": "실시간 편집 적용 중: 형태와 위치를 갱신하는 중입니다. 이미 적용된 직접 편집은 유지됩니다.",
  "Live edit failed: direct edits already applied are kept; geometry may still need updating.": "실시간 편집 실패: 이미 적용된 직접 편집은 유지되지만, 형태와 위치를 갱신해야 할 수 있습니다.",
  "Live edit. Showing a track applies on Generate if the Result did not draw it when its Session was loaded; after a Depth file or series change, or a change of the records the Depth files map to; for a custom stack row added since the last Generate or a stack the last Generate could not build; and, with a Circular custom track stack or Circular track widths or radii, for Hide GC Content and Hide GC Skew turned off": "실시간 편집. 트랙 표시는 다음 경우에 생성 시 적용됩니다. 세션을 불러왔을 때 결과에 그 트랙이 그려지지 않은 경우, 리드 깊이 파일 또는 계열을 변경하거나 리드 깊이 파일이 연결된 레코드를 변경한 후, 마지막 생성 이후 추가한 사용자 지정 스택 행이나 마지막 생성에서 만들 수 없었던 스택의 경우, 그리고 원형 다이어그램의 사용자 지정 트랙 스택이나 원형 다이어그램의 트랙 너비 또는 반지름을 사용할 때 ‘GC 함량 숨기기’와 ‘GC skew 숨기기’를 끈 경우",
  "Live edit: feature color, label text, and visibility update the current Result; geometry may rerender automatically.": "실시간 편집: feature 색, 레이블 텍스트, 표시 여부가 현재 결과에 반영되며, 형태와 위치는 자동으로 다시 렌더링될 수 있습니다.",
  "Live edit: legend text, order, stroke, and removal update the current Result.": "실시간 편집: 범례 텍스트, 순서, 윤곽선, 제거가 현재 결과에 반영됩니다.",
  "Live edit; the position applies on Generate after the Multi-Record Canvas change": "실시간 편집. ‘다중 레코드 캔버스’를 변경한 후에는 위치가 생성 시 적용됩니다.",
