  "Load with {substitutes}": "{substitutes} 글꼴로 불러오기",
  "Load with {substitutes}: the Session opens and its text is drawn in {substitutes}, the nearest available font.": "{substitutes} 글꼴로 불러오기: 세션이 열리고 텍스트는 사용 가능한 가장 비슷한 글꼴인 {substitutes} 글꼴로 그려집니다.",
  "Load with {substitutes}: the Session opens and its text is drawn in {substitutes}, the nearest available fonts.": "{substitutes} 글꼴로 불러오기: 세션이 열리고 텍스트는 사용 가능한 가장 비슷한 글꼴인 {substitutes} 글꼴로 그려집니다.",
