  "Lower bound for short records (0-1).": "짧은 레코드에 적용하는 반지름 비율의 하한입니다(0-1).",
  "MIT on GitHub": "GitHub의 MIT 라이선스",
  "Main": "주 레인",
  "Manual order and row assignment for multi-record canvas. Use Up/Down for left-to-right order within each row.": "다중 레코드 캔버스의 순서와 행 배정을 직접 설정합니다. 각 행 안의 왼쪽에서 오른쪽 순서는 ‘위로’/‘아래로’로 바꾸십시오.",
  "Manual scale interval for circular mode (in bp; must be > 0). Overrides automatic calculation.": "원형 모드의 눈금 간격을 직접 지정합니다(bp 단위, 0보다 커야 함). 자동 계산보다 우선합니다.",
  "Manual tick interval for Ruler scale style in bp (must be > 0). Leave blank to calculate automatically.": "축척 스타일이 ‘눈금자’일 때의 눈금 간격을 직접 지정합니다(bp 단위, 0보다 커야 함). 비워 두면 자동으로 계산합니다.",
  "Marks": "마크",
  "Match depth references to the selected record.": "리드 깊이 TSV의 참조 서열 이름을 선택한 레코드에 맞추십시오.",
  "Match height": "매치 높이",
  "Match style": "매치 스타일",
  "Matched sequences": "매치된 서열",
  "Matched {detail}": "일치: {detail}",
  "Max hits per protein for groups": "그룹 구성에 쓰는 단백질당 최대 히트 수",
  "Max target seqs": "최대 대상 서열 수",
  "Max unit gap": "최대 유닛 간격",
  "Maximum GC percentage for percent-mode clipping and axis scaling.": "백분율 모드의 클리핑과 축 범위 조정에 사용하는 최대 GC 백분율입니다.",
  "Maximum depth for clipping and normalization. Leave blank for auto.": "클리핑 및 정규화에 사용하는 최대 깊이입니다. 비워 두면 자동으로 설정됩니다.",
  "Maximum distinct subject proteins, not counting the protein itself, kept per query protein in each directed record-pair search to construct Similarity groups and Collinear blocks after result filtering. Leave blank to keep all hits passing the result filters. This does not limit raw LOSATP candidates or Pairwise display matches.": "결과 필터링 후 유사성 그룹과 공선성 블록을 구성하기 위해, 방향성 레코드 쌍 검색마다 쿼리 단백질당 유지하는 서로 다른 대상 단백질의 최대 수입니다(쿼리 단백질 자체는 세지 않음). 비워 두면 결과 필터를 통과한 모든 히트를 유지합니다. 원시 LOSATP 후보나 ‘쌍별 매치’ 모드에 표시되는 매치는 제한하지 않습니다.",
  "Maximum filtered matches displayed per query protein in Pairwise mode. This does not limit LOSATP candidates or Similarity/Collinear member evidence.": "‘쌍별 매치’ 모드에서 쿼리 단백질마다 표시하는 필터링된 매치의 최대 수입니다. LOSATP 후보나 유사성 그룹/공선성 블록의 구성원 판정에 쓰는 근거는 제한하지 않습니다.",
  "Maximum number of units (loci, or CDSs without a locus identifier; see Unit mode) between neighboring anchors of one block, on both records. 0 joins adjacent units only. With Diagonal drift 0, a gap is bridged only when both records skip the same number of units.": "한 블록의 인접 앵커 사이에 둘 수 있는 유닛(유전자좌, 또는 유전자좌 식별자가 없는 CDS; ‘유닛 모드’ 참조)의 최대 수이며, 두 레코드 모두에 적용됩니다. 0이면 인접한 유닛만 잇습니다. ‘대각선 이탈’이 0이면 두 레코드에서 건너뛰는 유닛 수가 같을 때만 간격을 잇습니다.",
  "Members": "구성원",
