  "Min length": "최소 길이",
  "Minimum GC percentage for percent-mode clipping and axis scaling.": "백분율 모드의 클리핑과 축 범위 조정에 사용하는 최소 GC 백분율입니다.",
  "Minimum Identity": "최소 동일성",
  "Minimum Length": "최소 길이",
  "Minimum connected genes required for a Collinear ribbon.": "공선성 리본에 필요한 연결된 유전자의 최소 수입니다.",
  "Minimum depth for clipping and normalization. Leave blank for auto.": "클리핑 및 정규화에 사용하는 최소 깊이입니다. 비워 두면 자동으로 설정됩니다.",
  "Minimum label-to-label vertical spacing for circular layouts in px.": "원형 레이아웃에서 레이블 사이의 최소 세로 간격(px)입니다.",
  "Minimum radius ratio": "최소 반지름 비율",
  "Minimum reserved height for the measured feature band, in pixels (px optional; positive). The actual reservation is max(measured, configured); this does not change feature glyph thickness, which is controlled by Feature Height (--feature_height). Auto values vary by record.": "측정된 feature 밴드에 확보하는 최소 높이(픽셀, px 생략 가능, 양수)입니다. 실제로 확보되는 높이는 max(measured, configured)이며, feature 도형의 두께는 바뀌지 않습니다. 이 두께는 ‘feature 높이’(--feature_height)로 조정합니다. 자동 값은 레코드마다 다릅니다.",
  "Mismatches": "불일치 수",
