  "Move the track, reduce widths, disable conflicting labels, or place it on the other side of the Axis.": "트랙을 이동하거나, 너비를 줄이거나, 충돌하는 레이블을 비활성화하거나, 축의 반대쪽에 배치하십시오.",
  "Move up within side": "같은 쪽 안에서 위로 이동",
  "Multi-Record Canvas": "다중 레코드 캔버스",
  "Multi-Record Canvas uses a grid. Turn it off to select one record.": "‘다중 레코드 캔버스’는 격자를 사용합니다. 레코드 하나를 선택하려면 끄십시오.",
  "Name": "이름",
  "Name / Species": "이름 / 종명",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. Leave blank for the default name: Depth, or Depth N when there are several series.": "이 행이 그리는 깊이 계열의 이름입니다. 입력하면 계열 카드, 이 계열을 그리는 모든 행, 범례 등 모든 곳에서 계열 이름이 바뀝니다. 비워 두면 기본 이름인 Depth(계열이 여러 개이면 Depth N)를 사용합니다.",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. The legend lists series in custom-stack order and omits series that no enabled row draws. Leave blank for the default name: Depth, or Depth N when there are several series.": "이 행이 그리는 깊이 계열의 이름입니다. 입력하면 계열 카드, 이 계열을 그리는 모든 행, 범례 등 모든 곳에서 계열 이름이 바뀝니다. 범례는 사용자 지정 스택 순서로 계열을 나열하며, 활성화된 어떤 행도 그리지 않는 계열은 생략합니다. 비워 두면 기본 이름인 Depth(계열이 여러 개이면 Depth N)를 사용합니다.",
  "Name of this Depth series in the legend. The legend label field of every Depth row that draws this series edits the same name. Leave blank for the default name: Depth, or Depth N when there are several series.": "범례에 표시되는 이 깊이 계열의 이름입니다. 이 계열을 그리는 모든 깊이 행의 범례 레이블 필드에서 같은 이름을 편집합니다. 비워 두면 기본 이름인 Depth(계열이 여러 개이면 Depth N)를 사용합니다.",
  "Name suggestions ({count})": "이름 제안({count})",
  "Names for all records in this file": "이 파일의 모든 레코드에 적용할 이름",
  "Needs a known feature strand.": "feature 가닥이 정해져 있어야 합니다.",
  "Negative skew color": "음의 skew 색",
  "New circular track renderer": "원형 다이어그램의 새 트랙 렌더러",
  "New color rule color": "새 색 규칙의 색",
