  "Raw LOSATP search limit per query protein (--max-target-seqs). In a within-record search the query protein itself counts as one target. Leave blank for an unbounded search, the default. Changing this value requires matching raw search results. Each mode remembers its own hit limits.": "쿼리 단백질당 원시 LOSATP 검색 한도(--max-target-seqs)입니다. 레코드 내 검색에서는 쿼리 단백질 자체도 대상 서열 하나로 셉니다. 기본값은 제한 없음이며, 제한 없이 검색하려면 비워 두십시오. 이 값을 바꾸면 그에 맞는 원시 검색 결과가 필요합니다. 모드마다 히트 한도를 따로 기억합니다.",
