  "Rotate linear labels in degrees (e.g., 45). In Above Feature mode, rotated labels start from each feature midpoint.": "선형 다이어그램의 레이블을 도 단위로 회전합니다(예: 45). ‘feature 위쪽’ 모드에서는 회전된 레이블이 각 feature의 중간점에서 시작합니다.",
