  "Row gap ratio": "행 간격 비율",
  "Rows above Axis are outside the circular axis; rows below Axis are inside it. Arrow buttons reorder within the current side only. Use Move outside Axis or Move inside Axis to cross the Axis.": "‘축’보다 위에 있는 행은 원형 축의 바깥쪽에, 아래에 있는 행은 안쪽에 그려집니다. 화살표 단추는 같은 쪽 안에서만 순서를 바꿉니다. 축을 넘어 이동하려면 ‘축 바깥쪽으로 이동’ 또는 ‘축 안쪽으로 이동’을 사용하십시오.",
  "Rows before Axis render above it; rows after Axis render below it. A Depth slot selects one global series and does not control vertical order. A record without a Depth TSV for that series does not draw it, but its space in the stack stays reserved.": "‘축’보다 앞에 있는 행은 축 위쪽에, 뒤에 있는 행은 축 아래쪽에 그려집니다. 깊이 슬롯은 전체에 공통인 계열 하나를 선택하며 세로 순서를 제어하지 않습니다. 해당 계열의 리드 깊이 TSV가 지정되지 않은 레코드에는 그 계열이 그려지지 않지만, 스택 공간은 확보된 상태로 남습니다.",
  "Rows {upper}–{lower}": "{upper}–{lower}행",
  "Rule error": "규칙 오류",
  "Ruler (Ticks)": "눈금자(눈금)",
  "Ruler Label Color": "눈금자 레이블 색",
  "Ruler Label Font Size": "눈금자 레이블 글꼴 크기",
  "Ruler label color": "눈금자 레이블 색",
  "Ruler on Axis": "축상 눈금자",
  "Rules are evaluated from top to bottom. Off hides the feature and leaves it out of protein search; Leave out of protein search keeps its visibility and leaves it out of protein search.": "규칙은 위에서 아래로 평가됩니다. ‘끔’은 feature를 숨기고 단백질 검색에서도 제외합니다. ‘단백질 검색에서 제외’는 표시 여부를 유지한 채 단백질 검색에서 제외합니다.",
  "Rules on the same qualifier: the first match wins.": "같은 한정자의 규칙: 처음 일치하는 규칙이 우선합니다.",
  "Run LOSAT": "LOSAT 실행",
