  "Run info": "실행 정보",
  "Run info is available after a successful manual generation.": "실행 정보는 수동 생성에 성공한 후에 표시됩니다.",
  "Run time": "실행 시간",
  "Running LOSAT: {completed}/{total} source jobs complete": "LOSAT 실행 중: 원본 작업 {completed}/{total}개 완료",
  "Running {program} comparisons for the circular diagram: {completed}/{total} jobs complete": "원형 다이어그램의 {program} 비교 실행 중: 작업 {completed}/{total}개 완료",
  "SPECIFIC RULES": "개별 규칙",
  "SVG ID": "SVG ID",
  "SVG and Interactive SVG exports carry the characters they use of this font, so they show it on computers without it. Fonts whose license forbids embedding are not embedded. Turned off, the SVG files keep only the font name. PNG export always draws this font, whatever this setting and the font's license. PDF export embeds this font whatever this setting; a font whose license forbids embedding is drawn in the nearest Liberation font.": "SVG 및 대화형 SVG 내보내기에는 이 글꼴에서 실제로 사용한 문자에 해당하는 글꼴 데이터가 포함되므로, 이 글꼴이 없는 컴퓨터에서도 같은 글꼴로 표시됩니다. 라이선스에서 포함을 금지하는 글꼴은 포함되지 않습니다. 끄면 SVG 파일에는 글꼴 이름만 남습니다. PNG 내보내기는 이 설정과 글꼴 라이선스에 관계없이 항상 이 글꼴로 그립니다. PDF 내보내기는 이 설정에 관계없이 이 글꼴을 포함하며, 라이선스에서 포함을 금지하는 글꼴은 가장 비슷한 Liberation 글꼴로 그립니다.",
  "SVG export error": "SVG 내보내기 오류",
  "Safe ({count})": "안전({count})",
  "Safe diagnostics": "안전한 진단 정보",
  "Same orientation": "같은 방향",
  "Satoshi Kawato": "Satoshi Kawato",
  "Save": "저장",
  "Save Raw LOSAT TSV": "원시 LOSAT TSV 저장",
  "Save Raw LOSAT TSV for #{from} to #{to}": "#{from} → #{to}의 원시 LOSAT TSV 저장",
  "Save Session": "세션 저장",
  "Save Session afterwards writes the current format. The file itself is not changed.": "이후에 ‘세션 저장’을 클릭하면 현재 형식으로 저장됩니다. 원래 파일은 변경되지 않습니다.",
  "Save Session needs current feature metadata for the loaded Result. Generate once, then Save Session.": "‘세션 저장’에는 불러온 결과의 최신 feature 메타데이터가 필요합니다. 한 번 생성한 후 ‘세션 저장’을 클릭하십시오.",
  "Save Session stores the current Result and settings draft. The SVG, Interactive SVG, PNG, and PDF buttons download the current Result. Neither applies pending settings.": "‘세션 저장’은 현재 결과와 설정 초안을 저장합니다. ‘SVG’, ‘대화형 SVG’, ‘PNG’, ‘PDF’ 단추는 현재 결과를 다운로드합니다. 둘 다 적용 대기 중인 설정을 적용하지 않습니다.",
  "Save stores the current Result and generation settings draft. It does not Generate.": "‘세션 저장’은 현재 결과와 생성 설정 초안을 저장합니다. ‘생성’은 실행하지 않습니다.",
  "Save the current Result and settings draft without generating": "생성하지 않고 현재 결과와 설정 초안 저장",
  "Saved Circular diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "저장된 원형 다이어그램: 설정({path})을 읽을 수 없어 이 다이어그램과 결과를 제외했습니다.",
  "Saved Linear diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "저장된 선형 다이어그램: 설정({path})을 읽을 수 없어 이 다이어그램과 결과를 제외했습니다.",
  "Saved alignment needs repair.": "저장된 맞춤을 복구해야 합니다.",
  "Saved comparison needs a decision": "저장된 비교의 처리 방법 결정 필요",
  "Saved comparison preserved as read-only": "저장된 비교가 읽기 전용으로 보존됨",
  "Saved diagram: the settings of the saved diagram ({path}) could not be read. The file loads as settings only; the saved Results, the GenBank, GFF and FASTA inputs, the feature list and the caches are left out.": "저장된 다이어그램: 저장된 다이어그램의 설정({path})을 읽을 수 없습니다. 이 파일은 설정만 불러오며, 저장된 결과, GenBank, GFF 및 FASTA 입력, feature 목록, 캐시는 제외됩니다.",
  "Saved names waiting for their original members: {names}": "원래 구성원이 없어 대기 중인 저장된 이름: {names}",
  "Saved other diagram: its settings ({path}) could not be read; that diagram and its Results are left out.": "저장된 다른 다이어그램: 설정({path})을 읽을 수 없어 이 다이어그램과 결과를 제외했습니다.",
  "Saving session. Retry after saving finishes.": "세션을 저장하는 중입니다. 저장이 끝난 후 다시 시도하십시오.",
  "Saving session…": "세션 저장 중…",
