  "Select Hide GC Content, or reduce GC Content Width (with Custom Track Slots on, the row width).": "‘GC 함량 숨기기’를 선택하거나 ‘GC 함량 트랙 너비’(‘사용자 지정 트랙 슬롯’이 켜져 있으면 행 너비)를 줄이십시오.",
  "Select Hide GC Skew, or reduce GC Skew Width (with Custom Track Slots on, the row width).": "‘GC skew 숨기기’를 선택하거나 ‘GC skew 트랙 너비’(‘사용자 지정 트랙 슬롯’이 켜져 있으면 행 너비)를 줄이십시오.",
  "Select a row to edit its label or open its details.": "행을 선택하면 레이블을 편집하거나 세부 정보를 열 수 있습니다.",
  "Select all": "모두 선택",
  "Select an anchor or Skip this record first.": "먼저 앵커를 선택하거나 ‘이 레코드 건너뛰기’를 클릭하십시오.",
  "Select an available series or delete this slot.": "사용 가능한 계열을 선택하거나 이 슬롯을 삭제하십시오.",
  "Select an eligible enabled anchor for an annotation track whose placement is Overlay anchor (Circular) or On axis (Linear).": "배치가 ‘오버레이 앵커’(원형) 또는 ‘축상’(선형)인 주석 트랙에는 조건에 맞는 활성화된 앵커를 선택하십시오.",
  "Select an exact reference record and feature before aligning.": "맞추기 전에 기준 레코드와 feature를 선택하십시오.",
  "Select an existing Depth TSV or remove the slot.": "기존 리드 깊이 TSV를 선택하거나 슬롯을 제거하십시오.",
  "Select an existing annotation set.": "기존 주석 세트를 선택하십시오.",
  "Select anchor": "앵커 선택",
  "Select annotation set": "주석 세트 선택",
  "Select diagnostics": "진단 정보 선택",
  "Select exact reference…": "기준 feature 선택…",
  "Select exactly one record.": "레코드를 하나만 선택하십시오.",
  "Select none": "모두 선택 해제",
  "Select one eligible enabled feature track as the axis.": "축으로 사용할 조건에 맞는 활성화된 feature 트랙을 하나 선택하십시오.",
  "Select one record to edit crop, orientation, and title lines.": "자르기, 방향, 제목 줄을 편집하려면 레코드를 하나 선택하십시오.",
  "Select preset...": "프리셋 선택…",
  "Select target record": "대상 레코드 선택",
  "Select the record to draw as one Circular diagram. Leave this on All records to draw each record as its own diagram.": "하나의 원형 다이어그램으로 그릴 레코드를 선택합니다. 각 레코드를 별도의 다이어그램으로 그리려면 ‘모든 레코드’로 두십시오.",
  "Select which feature types to draw.": "그릴 feature 유형을 선택하십시오.",
  "Select {label}, {coordinates} for {record}": "{record}의 {label}, {coordinates} 선택",
  "Select {label}, {coordinates}, strand {strand} for {record}": "{record}의 {label}, {coordinates}, 가닥 {strand} 선택",
  "Selected LOSAT comparisons require LOSATP Pairwise mode. For Similarity groups or Collinear blocks, choose Run LOSAT for all adjacent pairs.": "선택한 LOSAT 비교에는 LOSATP ‘쌍별 매치’ 모드가 필요합니다. 유사성 그룹이나 공선성 블록을 사용하려면 ‘모든 인접 쌍에 LOSAT 실행’을 선택하십시오.",
  "Selected action: {action}": "선택한 처리 방법: {action}",
  "Selected by user": "사용자가 선택함",
  "Selected comparisons cannot contain the same directed pair more than once.": "선택한 비교에 방향이 같은 동일한 쌍을 두 번 이상 포함할 수 없습니다.",
  "Selected feature": "선택한 feature",
  "Selected feature color": "선택한 feature 색",
