  "Selected pairs": "선택한 쌍",
  "Selected pairs ({count})": "선택한 쌍({count})",
  "Selected record was not found in the current file. Choose another record.": "현재 파일에서 선택한 레코드를 찾을 수 없습니다. 다른 레코드를 선택하십시오.",
  "Separate Strands": "가닥별 표시",
  "Sequence": "서열",
  "Sequence content is undefined: a record has no sequence after ORIGIN. Use a GenBank/DDBJ file that includes the sequence.": "서열 내용이 정의되지 않았습니다. ORIGIN 뒤에 서열이 없는 레코드가 있습니다. 서열이 포함된 GenBank/DDBJ 파일을 사용하십시오.",
  "Sequence is unavailable.": "서열을 사용할 수 없습니다.",
