  "Show primary coordinate ticks and labels in simple mode. The circular genome axis remains visible when this is off.": "단순 모드에서 주요 좌표 눈금과 레이블을 표시합니다. 이 옵션을 꺼도 원형 유전체 축은 계속 표시됩니다.",
  "Show stroke options": "윤곽선 옵션 표시",
  "Show the GC content percent axis line. Hiding the axis also hides percent tick marks and labels.": "GC 함량 백분율 축 선을 표시합니다. 축을 숨기면 백분율 눈금과 레이블도 숨겨집니다.",
  "Show the bottom scale bar or ruler and any coordinate ticks and labels drawn on record axes. Main record axes remain visible when this is off.": "아래쪽 축척 막대 또는 눈금자와, 레코드 축에 그려지는 좌표 눈금 및 레이블을 표시합니다. 이 옵션을 꺼도 레코드의 주축은 계속 표시됩니다.",
  "Show the depth coverage axis line. Hiding the axis also hides depth tick marks and labels.": "깊이 축 선을 표시합니다. 축을 숨기면 깊이 눈금과 레이블도 숨겨집니다.",
  "Show the label editor": "레이블 편집기 표시",
  "Show the members of {id}": "{id}의 구성원 표시",
  "Show this feature on the forward strand": "이 feature를 정방향 가닥에 표시",
  "Show this feature on the forward strand needs a feature on the + or − strand.": "‘이 feature를 정방향 가닥에 표시’하려면 feature가 + 또는 − 가닥에 있어야 합니다.",
  "Show this label": "이 레이블 표시",
  "Showing and hiding apply at once; leaving a feature out of protein search applies on Generate": "표시와 숨기기는 즉시 적용되고, feature를 단백질 검색에서 제외하는 설정은 생성 시 적용됩니다",
  "Showing the last successful Result again; your changes were not applied. Correct the cause and retry.": "마지막으로 성공한 결과를 다시 표시하고 있습니다. 변경 사항이 적용되지 않았습니다. 원인을 해결한 후 다시 시도하십시오.",
  "Showing the last successful Result; your changes were not applied.": "마지막으로 성공한 결과를 표시하고 있습니다. 변경 사항이 적용되지 않았습니다.",
  "Showing the last successful result.": "마지막으로 성공한 결과를 표시하고 있습니다.",
  "Similarity alignment applied.": "유사성 맞춤을 적용했습니다.",
  "Similarity group": "유사성 그룹",
