  "Similarity group {id}: {summary}": "유사성 그룹 {id}: {summary}",
  "Similarity groups": "유사성 그룹",
  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT, so they do not run on pairs set one by one in Selected pairs. Choose Run LOSAT for all adjacent pairs, or choose Pairwise matches.": "유사성 그룹과 공선성 블록은 인접한 모든 쌍을 LOSAT으로 비교하므로, ‘선택한 쌍’에서 하나씩 설정한 쌍에서는 실행되지 않습니다. ‘모든 인접 쌍에 LOSAT 실행’ 또는 ‘쌍별 매치’를 선택하십시오.",
  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT.": "유사성 그룹과 공선성 블록은 인접한 모든 쌍을 LOSAT으로 비교합니다.",
  "Similarity groups appear after a Linear comparison with Similarity groups turned on.": "유사성 그룹은 ‘유사성 그룹’을 켜고 선형 다이어그램에서 비교를 실행한 후에 표시됩니다.",
  "Similarity groups: {count} description edit ({path}) names a group the saved Result does not have and was dropped.": "유사성 그룹: 설명 편집 {count}건({path})은 저장된 결과에 없는 그룹을 가리키므로 제외했습니다.",
  "Similarity groups: {count} description edits ({path}) name a group the saved Result does not have and were dropped.": "유사성 그룹: 설명 편집 {count}건({path})은 저장된 결과에 없는 그룹을 가리키므로 제외했습니다.",
  "Similarity groups: {count} name edit ({path}) names a group the saved Result does not have and was dropped.": "유사성 그룹: 이름 편집 {count}건({path})은 저장된 결과에 없는 그룹을 가리키므로 제외했습니다.",
  "Similarity groups: {count} name edits ({path}) name a group the saved Result does not have and were dropped.": "유사성 그룹: 이름 편집 {count}건({path})은 저장된 결과에 없는 그룹을 가리키므로 제외했습니다.",
