  "Similarity-group member product": "유사성 그룹 구성원 산물",
  "Similarity-group member protein ID": "유사성 그룹 구성원 단백질 ID",
  "Simple mode only. Above places features above the axis, Features on axis centers them on it, and Below places them below it. Use Reset to copy this choice into the custom stack.": "단순 모드에서만 적용됩니다. ‘위쪽’은 feature를 축 위쪽에, ‘축상 feature’는 축을 중심으로, ‘아래쪽’은 축 아래쪽에 배치합니다. 이 선택을 사용자 지정 스택에 복사하려면 ‘초기화’를 사용하십시오.",
  "Simple mode only. Display a GC content track; use Reset to copy it into the custom stack.": "단순 모드에서만 적용됩니다. GC 함량 트랙을 표시합니다. 사용자 지정 스택에 복사하려면 ‘초기화’를 사용하십시오.",
  "Simple mode only. Display a GC skew track; use Reset to copy it into the custom stack.": "단순 모드에서만 적용됩니다. GC skew 트랙을 표시합니다. 사용자 지정 스택에 복사하려면 ‘초기화’를 사용하십시오.",
  "Simple mode only. Display depth coverage tracks from uploaded TSV files; use Reset to copy them into the custom stack.": "단순 모드에서만 적용됩니다. 업로드한 TSV 파일의 깊이 트랙을 표시합니다. 사용자 지정 스택에 복사하려면 ‘초기화’를 사용하십시오.",
  "Simple mode only. Use Reset to rebuild the custom stack from this setting.": "단순 모드에서만 적용됩니다. 이 설정으로 사용자 지정 스택을 다시 구성하려면 ‘초기화’를 사용하십시오.",
