  "Step size for GC content/skew. Default: 100bp (<1Mb), 1kb (<10Mb), 10kb (>=10Mb).": "GC 함량/skew의 스텝 크기입니다. 기본값: 100bp(<1Mb), 1kb(<10Mb), 10kb(>=10Mb).",
  "Step size for depth aggregation. Blank: a tenth of the GC step, at least 1 bp.": "깊이 집계의 스텝 크기입니다. 비워 두면 GC 스텝의 10분의 1(최소 1 bp)입니다.",
  "Strain": "균주",
