  "Strand": "가닥",
  "Strand: neighboring anchors of a block follow its strand orientation and the gene order. Gene order: they follow the gene order only.": "‘가닥’: 블록의 인접 앵커가 해당 블록의 가닥 방향과 유전자 순서를 따릅니다. ‘유전자 순서’: 인접 앵커가 유전자 순서만 따릅니다.",
  "Stretch the overlay from its anchor to this slot, over every slot between them (to_slot). None: the overlay's own band.": "오버레이를 앵커에서 이 슬롯까지, 그 사이의 모든 슬롯에 걸쳐 늘립니다(to_slot). ‘없음’이면 오버레이 자체의 밴드만 사용합니다.",
