  "Suggest a translation fix": "번역 수정 제안하기",
  "Summary": "요약",
  "Supply GenBank input or matching GFF3 and FASTA inputs.": "GenBank 입력 또는 서로 대응하는 GFF3 및 FASTA 입력을 지정하십시오.",
  "Supply a comparison sequence file (FASTA, GenBank, or DDBJ) or BLAST outfmt 6/7 as required.": "필요에 따라 비교 서열 파일(FASTA, GenBank 또는 DDBJ) 또는 BLAST outfmt 6/7을 지정하십시오.",
  "Supply a matching FASTA input for each GFF3 input.": "각 GFF3 입력에 맞는 FASTA 입력을 지정하십시오.",
  "Supply at least three tab-separated columns.": "탭으로 구분된 열을 3개 이상 지정하십시오.",
  "Supply both region endpoints or leave both empty.": "영역의 시작 위치와 끝 위치를 모두 지정하거나 둘 다 비워 두십시오.",
  "Supply four or five tab-separated columns.": "탭으로 구분된 열을 4개 또는 5개 지정하십시오.",
