  "Swatch size": "색 견본 크기",
  "TLOSATX gencode for sequence {n}": "서열 {n}의 TLOSATX 유전 암호표",
  "TSV file of rules: feature type, qualifier, regular expression, color, and optional legend name.": "규칙을 적은 TSV 파일입니다. 열은 feature 유형, 한정자, 정규식, 색, 범례 이름(선택 사항)입니다.",
  "Tab-separated value (TSV) file of feature type and color. Feature types not listed keep the selected palette colors.": "feature 유형과 색을 적은 탭 구분 값(TSV) 파일입니다. 목록에 없는 feature 유형은 선택한 팔레트의 색을 유지합니다.",
