  "{count} annotation of a selected feature that the current diagram does not draw was not exported.": "선택한 feature 중 현재 다이어그램에 그려지지 않는 feature의 주석 {count}개는 내보내지 않았습니다.",
  "{count} annotation of a selected feature was written as record=#<position> and feature_selector=hash=<feature hash>. It names the same feature only while the record order stays as drawn.": "선택한 feature의 주석 {count}개를 record=#<position> 및 feature_selector=hash=<feature hash> 형식으로 내보냈습니다. 이 주석은 레코드 순서가 그려진 그대로일 때만 같은 feature를 가리킵니다.",
